        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Book a Test Appointment</p>
          <p class="text-slate-600 text-sm">Use a different email to book a test appointment through your link.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Check All Messages</p>
          <p class="text-slate-600 text-sm">Verify confirmation and reminder emails arrive with correct details.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Test Cancel/Reschedule</p>
          <p class="text-slate-600 text-sm">Cancel or reschedule the test to ensure the system handles changes correctly.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Test the Booking Process',
      lesson_number = 8,
      sort_order = 8,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Test the Booking Process';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Test the Booking Process

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 6 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 6 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'test-booking-process' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson test-booking-process not found in module 6';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you test your booking link before sharing it?', 
    '["It is optional","To make sure confirmations, reminders, and meeting details all work properly","To waste time","To create fake appointments"]'::jsonb,
    'To make sure confirmations, reminders, and meeting details all work properly',
    'Testing ensures your booking process works correctly before real prospects use it, protecting your professional reputation.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you use to book a test appointment?', 
    '["Your admin email","A different email address than your admin email","No email","A fake email that doesn''t exist"]'::jsonb,
    'A different email address than your admin email',
    'Use a different email address than your admin email to simulate the real prospect experience and ensure all notifications work correctly.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you verify during testing?', 
    '["Only the booking page design","Confirmation, reminders, meeting details, calendar sync, and cancel/reschedule","Nothing, it always works","Only the color scheme"]'::jsonb,
    'Confirmation, reminders, meeting details, calendar sync, and cancel/reschedule',
    'Thorough testing includes verifying confirmations, reminders, meeting details, calendar synchronization, and the cancel/reschedule process.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
